using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.FibonacciAtomic.Observer;
internal sealed class NativeGroundSolutionSpaceDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Arith/FibonacciAtomic/Observer/NativeGroundSolutionSpace.";
    private static DocumentBlock Entry(string id, string declaration, string title, string prose, DescribeRole role) =>
        Describe.Lean(DescribeId.Create(id),
            DeclarationHandle.Create(Prefix + declaration), H(title), StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))), role);
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "All native ground solutions and constraint pullback.", H("All native ground solutions and constraint pullback"), Blocks(
            Entry("schema-source", "Source", "Native source carrier", "Source is the repository FreeMagma Bool carrier, preserving both Boolean generators and ordered binary trees.", DescribeRole.Definition),
            Entry("schema-equations", "Equations", "Finite original equations", "Equations are finite lists of pairs of original Term X expressions. All original variables remain in X, even when absent from these equations.", DescribeRole.Definition),
            Entry("encodeequations", "encodeEquations", "Faithful equation encoding", "Both sides of every original equation are encoded by the same complete variable presentation.", DescribeRole.Definition),
            Entry("schema-sol", "Sol", "Original ground solutions", "An assignment from all original X to native Source solves C exactly when evaluation agrees on both sides of every equation in C.", DescribeRole.Definition),
            Entry("groundvalue", "groundValue", "Ground value lookup", "A successfully decoded original identifier receives the encoding of its assigned native ground source.", DescribeRole.Definition),
            Entry("groundsubst", "groundSubst", "Full finite ground assignment", "The finite substitution binds every original identifier to its assigned native ground tree and leaves other identifiers unbound.", DescribeRole.Definition),
            Entry("groundsubst-find", "groundSubst_find", "Every original coordinate is bound", "For every original x, the ground substitution lookup at code x is exactly some of the ground encoding of v x.", DescribeRole.Theorem),
            Entry("groundsubst-other", "groundSubst_other", "Other identifiers stay unbound", "For every identifier distinct from every original code, lookup in the finite ground substitution is none.", DescribeRole.Theorem),
            Entry("groundsubst-evaluate", "groundSubst_evaluate", "Encoding commutes with evaluation", "For every original native term, applying the full ground substitution to its encoding equals the ground encoding of evaluation under that assignment.", DescribeRole.Theorem),
            Entry("encodeground-injective", "encodeGround_injective", "Ground encoding is injective", "The encoding retains both distinct Boolean labels and both ordered children at every branch.", DescribeRole.Theorem),
            Entry("groundsubst-sol", "groundSubst_sol", "A common finite substitution", "Every original ground solution produces one finite Strata substitution solving all encoded equations simultaneously.", DescribeRole.Theorem),
            Entry("native-complete", "native_complete", "Native satisfiability prevents failure", "Every original ground solution v on all X is encoded as one finite groundSubst using the complete presentation enumeration. groundSubst_evaluate proves that this same substitution solves each encoded equation; absorption of the empty state is automatic. The unrestricted Constraints.unify_complete proof then produces success of the actual native call. Both the finite evaluation correspondence and unrestricted completeness remain live in this application; no groundness or well-formedness premise is imposed on the arbitrary R of the generic completeness theorem.", DescribeRole.Theorem),
            Entry("output-native", "output_native", "Actual successful output shape", "Every stored value of a successful encoded-native output has the exact native constructor shape.", DescribeRole.Theorem),
            Entry("equations-supported", "equations_supported", "Equation identifier support", "Every free identifier in the encoded equation list is the code of an original variable.", DescribeRole.Theorem),
            Entry("output-supported", "output_supported", "Output value support", "Every free identifier of every stored successful output value remains in the original variable alphabet.", DescribeRole.Theorem),
            Entry("action", "action", "Total original-variable action", "For every original x, decode the actual substituted code x. The total action includes aliases, unbound variables and variables unused by C; its fallback is unreachable after actual native success.", DescribeRole.Definition),
            Entry("action-encode", "action_encode", "The total action is the actual substitution", "For every successful native output and every x in the full original type, encoding action x equals the actual Strata substitution applied to the variable code x.", DescribeRole.Theorem),
            Entry("schema-d", "D", "Actual bound subset", "D consists exactly of original variables whose identifiers occur in the successful substitution key set.", DescribeRole.Definition),
            Entry("schema-y", "Y", "Complementary parameter type", "Y is the subtype of all original variables outside D, including unused original variables.", DescribeRole.Definition),
            Entry("termvars", "termVars", "Actual term variable support", "The variable list retains every variable occurrence and concatenates the lists of ordered children.", DescribeRole.Definition),
            Entry("encode-variables", "encode_variables", "Exact encoded support", "The free-variable list of an encoded native term is exactly the list of its original variables mapped through the code.", DescribeRole.Theorem),
            Entry("action-support", "action_support", "Support lies in the complement", "Every variable occurring in any total action value lies outside the actual key subset D. The algorithm invariant excludes every key from every substituted value.", DescribeRole.Theorem),
            Entry("action-identity", "action_identity", "Identity on unbound original variables", "For every original variable outside D, its total action is exactly that same variable leaf.", DescribeRole.Theorem),
            Entry("bound-iff-nonidentity", "bound_iff_nonidentity", "Exact bound characterization", "For every successful output and original x, membership in D is equivalent to the total action being different from the original variable leaf.", DescribeRole.Theorem),
            Entry("restrictterm", "restrictTerm", "Relabeling supported terms", "A term whose variables lie outside D is relabeled into the complementary subtype Y, preserving all Boolean leaves and ordered branches.", DescribeRole.Definition),
            Entry("sigma", "sigma", "Normalized parameter terms", "The total action at every original x is relabeled into Term Y using its proved support in Y. No recursive normalization algorithm is introduced.", DescribeRole.Definition),
            Entry("schema-ext", "Ext", "The same extension map", "For arbitrary w from Y to native Source, Ext w at original x is evaluation of sigma x under w.", DescribeRole.Definition),
            Entry("restriction", "restriction", "Exact original restriction", "An original assignment is restricted to the complementary original-variable subtype Y.", DescribeRole.Definition),
            Entry("evaluate-restrictterm", "evaluate_restrictTerm", "Relabeling preserves evaluation", "Evaluating a relabeled term under an assignment restricted to Y equals evaluating the original term under the whole original assignment.", DescribeRole.Theorem),
            Entry("restriction-ext", "restriction_Ext", "Extension has exact restriction", "For every arbitrary assignment w on Y, restricting Ext w returns exactly w.", DescribeRole.Theorem),
            Entry("schema-ext-restriction", "Ext_restriction", "Every original ground solution factors", "For every original ground solution v on all X, Ext of its restriction equals v at every original coordinate. The original arbitrary-substitution MGU law supplies the factorization.", DescribeRole.Theorem),
            Entry("shape-ground", "shape_ground", "Empty support produces native ground", "A type tree with exact native Shape and empty free-variable list is the encoding of an actual Boolean-leaf ground source.", DescribeRole.Theorem),
            Entry("encodeground-freevars", "encodeGround_freeVars", "Ground encoding has empty support", "Every actual native ground source encodes to a tree with no free variables.", DescribeRole.Theorem),
            Entry("native-ground-iff", "native_ground_iff", "Exact unique native ground detection", "For every tree having exact native Shape, empty variable support is equivalent to existence of exactly one native Source tree with that encoding. The Shape hypothesis excludes foreign nullary constructors and bit vectors.", DescribeRole.Theorem),
            Entry("substitute", "substitute", "Native simultaneous action", "The existing free-magma lift extends a total assignment of native terms to simultaneous substitution on all original terms.", DescribeRole.Definition),
            Entry("substitute-evaluate", "substitute_evaluate", "Evaluation composition", "Evaluating simultaneous term substitution equals evaluating the original term under the assignment obtained by evaluating each substituted variable term.", DescribeRole.Theorem),
            Entry("action-substitute-encode", "action_substitute_encode", "Native action and Strata substitution commute", "Encoding simultaneous total native action on any original term equals actual Strata substitution on that term encoding.", DescribeRole.Theorem),
            Entry("action-idempotent", "action_idempotent", "Normalization supplied by the algorithm", "For every original x after actual native success, another simultaneous application of the total action leaves action x unchanged. The original SubstInfo well-formedness and subst_idempotent theorem supply normalization.", DescribeRole.Theorem),
            Entry("fill", "fill", "Comparison assignment", "A parameter assignment is extended to original X by giving bound coordinates one fixed Boolean leaf. Those coordinates never occur in sigma and cannot affect Ext.", DescribeRole.Definition),
            Entry("restriction-fill", "restriction_fill", "Filling preserves parameter values", "Restricting the comparison assignment to Y returns the supplied parameter assignment exactly.", DescribeRole.Theorem),
            Entry("schema-ext-evaluate-action", "Ext_evaluate_action", "Extension evaluates the total action", "Ext w at any original x equals evaluation of action x under the comparison assignment. This uses only relabeling and the support in Y.", DescribeRole.Theorem),
            Entry("schema-ext-sol", "Ext_sol", "All parameter assignments give solutions", "For every successful actual native output and every arbitrary w on Y, the same Ext w solves every original equation in C. No injectivity of arbitrary ground evaluation is assumed.", DescribeRole.Theorem),
            Entry("solutionequiv", "solutionEquiv", "The complete ground solution set", "For every original variable type with complete finite presentation, every finite original equation list C and every successful output S from empty substitution, extension and restriction form the exact equivalence (Y to Source) with the subtype of all original assignments solving C. Empty X and empty C remain included.", DescribeRole.Definition),
            Entry("schema-diseq", "Diseq", "All original disequalities", "Every old disequality is evaluated on the entire original assignment. None is dropped when its variables are absent from the new equation list.", DescribeRole.Definition),
            Entry("constrainedequiv", "constrainedEquiv", "Exact guard and disequality pullback", "For every old disequality list Delta and arbitrary predicate G on original assignments, the same extension and restriction give an equivalence between parameter assignments satisfying Diseq Delta (Ext w) and G (Ext w), and original assignments satisfying Sol C v, Diseq Delta v and G v. This constrained parameter subtype is not assumed to be a product, and no decision procedure for arbitrary G is asserted.", DescribeRole.Definition),
            Entry("total-action-spec", "total_action_spec", "All-variable normalized action laws", "For every successful output and every original x, simultaneous action fixes action x; every variable in action x belongs to Y; outside D the action is the original variable; and D is exactly the set of nonidentity actions.", DescribeRole.Theorem),
            Entry("output-keys", "output_keys", "Keys stay original", "Every key in a successful output is an original-variable code. The original keys_incl supplier prevents introduction of foreign identifiers.", DescribeRole.Theorem),
            Entry("grounddecoder", "groundDecoder", "Exact native ground decoder", "The executable decoder admits only the two nullary Boolean leaves and ordered binary pairs. It rejects variables, bit vectors, foreign names and malformed arities.", DescribeRole.Definition),
            Entry("grounddecoder-exact", "groundDecoder_exact", "Ground decoding is exact", "Decoding a type tree to a particular Source succeeds exactly when the tree is that source encoding. No foreign constructor can be mistaken for native ground.", DescribeRole.Theorem),
            Entry("schema-parameterization", "Parameterization", "The complete normalized solution interface", "A successful state supplies its actual original-variable keys, normalized total action, complementary parameters, exact nonidentity and ground characterizations, and all-ground-solutions and constrained-space equivalences.", DescribeRole.Definition),
            Entry("parameterization", "parameterization", "Actual algorithm parameterization", "Every successful encoded-native output realizes the full Parameterization interface. Every original variable remains represented; every old disequality and arbitrary already established guard is pulled back along the same Ext.", DescribeRole.Definition))));
}
